import { useState } from "react";
import type { AccordionProps } from "../types/accordion";
import AccordionItem from "./AccordionItem";

export default function Accordion({items, allowMultiple}: AccordionProps) {
    const [openIds, setOpenIds] = useState<number[]>([]);

    const handleToggle = (id: number) => {
        setOpenIds((currentIds) => {
            const isOpen = currentIds.includes(id);

            if(allowMultiple) {
                return isOpen ? currentIds.filter((currentId) => currentId !== id) : [...currentIds, id];
            }

            return isOpen ? [] : [id];
        });
    }
    return (
        <div className="accordion">
            {items.map((item) => (
                <AccordionItem
                    key={item.id}
                    item={item}
                    isOpen={openIds.includes(item.id)}
                    onToggle={() => handleToggle(item.id)}>

                </AccordionItem>
            ))}
        </div>
    )
}

files.src\\components\\AccordionItem.tsx:
import type { AccordionItemProps } from "../types/accordion";

export default function AccordionItem({item, isOpen, onToggle}: AccordionItemProps) {
    return(
        <div className="accordion-item">
            <button
                className="accordion-header"
                onClick={onToggle}
                aria-expanded={isOpen}
                aria-controls={`accordion-content-${item.id}`}>
                    <span>
                        {item.question}
                    </span>
                    <span className="accordion-icon">
                        {isOpen ? '-' : '+'}
                    </span>
            </button>

            {isOpen && (
                <div
                    className="accordion-content"
                    id={`accordion-content-${item.id}`}
                    role="region"
                    aria-labelledby={`accordion-content-${item.id}`}
                    >
                        <p>{item.answer}</p>
                </div>
            )}
        </div>
    )

}

