/* Global */
* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family:
    Inter,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  background: #f5f7fb;
  color: #1f2937;
}

/* Main container */
.container {
  max-width: 1100px;
  margin: 50px auto;
  padding: 0 20px;
}

/* Header */
header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

header h1 {
  margin: 0 0 6px;
  font-size: 28px;
}

header p {
  margin: 0;
  color: #6b7280;
}

/* Search */
input {
  width: 100%;
  padding: 12px 14px;
  margin-bottom: 20px;

  border: 1px solid #d1d5db;
  border-radius: 8px;

  background: white;
  font-size: 15px;

  outline: none;
}

input:focus {
  border-color: #6366f1;

  box-shadow:
    0 0 0 3px rgba(99, 102, 241, 0.1);
}

/* Table container */
.table-wrapper {
  overflow-x: auto;

  background: white;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
}

/* Table */
table {
  width: 100%;
  border-collapse: collapse;
}

/* Table header */
th {
  padding: 14px 16px;

  background: #f9fafb;
  color: #374151;

  font-size: 14px;
  font-weight: 600;
  text-align: left;

  border-bottom: 1px solid #e5e7eb;
}

/* Table cells */
td {
  padding: 14px 16px;

  color: #4b5563;
  font-size: 14px;

  border-bottom: 1px solid #f0f0f0;
}

/* Row hover */
tbody tr:hover {
  background: #f9fafb;
}

/* Remove border from last row */
tbody tr:last-child td {
  border-bottom: none;
}

/* Empty state */
.empty {
