                                onMouseEnter={() => setHover(star)}
                                onMouseLeave={() => setHover(0)}
                                className={ star <= (rating || hover) ? 'star active' : 'star'}
                                >{`\u2605`}</button>
                        )
                    })
                }
            </div>
            <p>
                {rating > 0 ? `You rated ${rating}/5` : "Select a rating"}
            </p>
        </div>
    )
}

