        <div key={comment.id} style={{ marginBottom: '8px' }}>
          <em>"{comment.text}"</em> - {comment.author}
        </div>
      ))}
    </div>
  );
}

function Solution() {
  return (
    <div style={{ padding: '20px', fontFamily: 'Arial' }}>
